#[repr(u8)]
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize, num_enum::TryFromPrimitive)]
pub enum FlexBufferType {
    /// Nulls are represented with `()` in Rust.
    Null = 0,
    /// Variable width signed integer: `i8, i16, i32, i64`
